          {text:'船が長く寄港しなくなれば、宿や茶屋を訪れる人の数も変わる。かつて町を賑わせた待ち時間は、同じようには生まれなくなった。ただし、船も商いも一度に消え去ったわけではない。御手洗の役割は、新しい交通のあり方に合わせて少しずつ変わっていった。',refs:[]},
          {text:'港の地形が急に変わったのではない。海の向こうで、船の進み方や人と物の運ばれ方が変わったのである。町の歴史を読むときは、目の前の岸壁だけでなく、そこへつながっていた航路にも思いを向けたい。',refs:[]}
