    provisionalConclusion:'御手洗では、潮や風で船が動けない時間が地域の経済資源になった。滞在が宿泊・飲食・商業・接客・荷役の需要を生み、その需要を処理するために狭い海岸へ都市機能が集積した。交通技術の進歩でその需要は消えたが、更新されなかった町並みが現在は文化資産として残っている。',
    openQuestions:['寄港船数と船宿・茶屋数の関係を時系列で復元できるか','御手洗と鞆・下津井で滞在時間と消費構造はどれほど違ったか','航海技術革新後の人口・商業縮小を定量化できるか'],
