          {text:'一つの商家に、売る場所、保管する場所、金勘定をする場所、暮らす場所が重なっている。町家は単なる住まいでも、富を飾る建物でもなかった。商品と人とお金を動かすための、小さな経営の拠点だったのである。',refs:[2]},
          {text:'小田家には古文書や生活用具も残り、現在は「商家博物館むろやの園」として紹介されている。建物が残ったことで、そこで行われた仕事をたどる手掛かりも残った。',refs:[2]}
