    provisionalConclusion:'三原の地域性は、港町・城下町・工業都市・高速交通都市という個別の肩書ではなく、交通の結節点という場所の役割を、新しいインフラへ何度も載せ替えてきたことにある。',
    openQuestions:['三原城下と鉄道敷設前後の土地利用を同一地図上で重ねられるか','港湾貨物と鉄道貨物の連携を時系列で追えるか','空港・新幹線・港の利用者流動が現在どこまで相互補完しているか'],
