    provisionalConclusion:'引田では、風待ち・潮待ちに適した港を核として、その港を監視・支配する城と、寄港需要を受け止める商家町が近接して形成された。城・港・町を別々に見るより、「価値ある港をどう守り、どう経済へ変えたか」という一つの問いで読む方が地域の構造が見えやすい。',
    openQuestions:['引田港の寄港船数や主要取扱品を時系列で復元できるか','引田城の機能と港湾支配の関係を史料でどこまで確認できるか','ハマチ養殖・醤油等の港湾利用と近代鉄道の役割分担を追えるか'],
