    heroPhotoId:'photo-ako-salt-terrace',
    lead:"赤穂の塩づくりは、かつて海辺に広がる塩田で、日光と風を使う仕事だった。ところが1972年に塩田製塩は終わる。それでも今、赤穂には塩をつくる工場がある。なぜ生産の場所と技術が変わっても、製塩事業は残ったのだろう。手がかりは、塩田が終わる前から、製塩業者が会社をつくり技術を切り替える道を選んでいたことにある。",
