          {text:'赤穂では17世紀以降、遠浅の海岸に大規模な入浜式塩田が築かれた。堤防と水路を整え、潮の満ち引きを利用して海水を塩田へ導き、太陽と風で濃縮する。海岸そのものが巨大な生産設備だった。',refs:[1]},
          {text:'ここで使っていたのは海水だけではない。遠浅の地形、干満、日照、広い土地、労働力、煎熬設備が一体になって初めて塩になる。だから長い間、赤穂の製塩業と塩田はほぼ同じ意味だった。',refs:[]},
          {text:'しかし20世紀になると、その「塩田を使うこと」自体が製塩業の制約になっていく。生産性を上げるには、まず塩田の中身から変える必要があった。',refs:[]}
