          {text:"日本海水の赤穂工場は、現在も海水をイオン交換膜で濃縮し、真空蒸発缶で煮詰めて塩を生産している。以前と同じ海水を原料にしていても、使う設備や仕事は塩田時代とは違う。",refs:[4]},
          {text:"製塩事業の継続と、かつて塩田で働いた人々の雇用や技能の継承は同じではない。誰が新しい工場で働くようになったのかは、企業史や労働史の記録をさらに調べる必要がある。",refs:[2,4]}
