          {text:"塩田の土地が工業用地や市街地になった話は、別の作品でたどるべき歴史である。ここでは土地よりも、製塩をやめずに続けるため、業者がどのような経営と技術の選択をしたのかに注目したい。",refs:[1,2]},
          {text:"赤穂の塩を手に取るとき、地面に広げた海水ではなく、膜と蒸発缶を通って塩になる海水を思い浮かべてみる。古い技術を手放したからこそ、塩をつくる仕事が残ることもある。",refs:[2,4]}
