          {text:'下津井は備讃瀬戸に面し、本州と四国の間で潮が複雑に動く場所にある。港町の歴史だけでなく、食文化の側から見ても「流れの速い海」が基層にある。',refs:[]},
          {text:'ただし、潮流が速ければ自動的にたこめしが生まれるわけではない。海の条件から料理までの間には、漁業と暮らしがある。',refs:[]}
