          {text:'この伝承が示すのは、郷土料理が最初から観光客向けの名物として生まれたのではないことだ。まず仕事の現場で手に入る食材を、日常の食事へ組み込むところから始まった。',refs:[]},
          {text:'漁場と食卓の距離が短いほど、獲れた魚介をどう食べるかという試行錯誤が起きやすい。料理は、生態系だけでなく労働の現場からも生まれる。',refs:[]}
