          {text:'新鮮なタコは刺身や煮付けにもできる。実際、下津井周辺ではイイダコの煮付けも伝承されている。つまり一つの海産物から複数の調理法が生まれている。',refs:[2]},
          {text:'米と一緒に炊けば、少量のタコでも家族や船員で分けやすく、主食と副食を一つの鍋で調理できる。こうした生活上の合理性が地域料理として定着した可能性は高いが、具体的な成立過程はさらに史料が必要である。',refs:[]}
