          {text:'さらに岡山県は、瀬戸内海で過去の富栄養化、藻場・干潟の減少、その後の水質改善と栄養塩不足など、海域環境が長期的に変化してきたことを整理している。',refs:[4]},
          {text:'郷土料理を守るとは、レシピだけを保存することではない。食材を支える海の環境、漁業者、資源管理まで含めて持続させなければ、料理の基盤そのものが弱くなる。',refs:[]}
