          {text:'だから「下津井はタコが有名」という結論だけでは惜しい。なぜその海にタコがいて、なぜ人がそれを獲り、なぜ米と炊き、なぜ今も地域料理として残るのか。順に追うことで、料理が自然と社会の接点であることが見えてくる。',refs:[]},
          {text:'そして現在は、資源減少という新しい条件が加わっている。下津井のガストロノミーは、過去の文化ではなく、変化する海と向き合う現在の課題でもある。',refs:[3,4]}
