    provisionalConclusion:"錦海塩田跡地は、海を締め切り、排水を続けることで生まれた土地である。塩づくりが終わり、産業廃棄物処分も終わっても、浸水を防ぐ管理の必要は残った。瀬戸内市は跡地を取得し、貸付と安全・安心施設の整備を組み合わせて太陽光発電所を誘致した。この作品の主題は、発電所がいつ終わるかではなく、人工の土地を維持しながら何に使い直したかという現在に至る選択である。",
